      const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '' }).map(r => Object.fromEntries(Object.entries(r).map(([k, v]) => [A.norm(k), A.norm(v)]))).filter(r => r['الاسم']);
