    if (!('Notification' in window)) { A.toast(isIOS() ? 'على الآيفون: ثبّت المنصة على الشاشة الرئيسية أولاً ثم فعّل الإشعارات من داخلها' : 'هذا المتصفح لا يدعم الإشعارات', 'err'); return false; }
