  const W = (e, q) => +(e.weights[q] ?? 1);
  // درجة السؤال للطالب: المقالي = قيمة الدائرة التي ظللها المعلم، والموضوعي = الدرجة كاملة إن طابق المفتاح
  const markQ = (e, qs, key, ans, marks, q) => { const w = W(e, q), Q = qs[q] || {}; if (marks && marks[q] != null && marks[q] !== '') return Math.min(w, Math.max(0, +marks[q] || 0)); const a = ans ? ans[q] : undefined; if (a === undefined || a < 0) return 0; if (Q.teacher) return Math.min(w, (Q.vals || [])[a] || 0); return a === key[q] ? w : 0; };
  const scoreOf = (e, model, ans, marks) => { const key = (e.models.find(m => m.name === model) || e.models[0] || { answers: [] }).answers, qs = QS(e); let s = 0, mx = 0; for (let q = 0; q < e.n_questions; q++) { mx += W(e, q); s += markQ(e, qs, key, ans, marks, q); } return [Math.round(s * 100) / 100, mx]; };
  const markOf = (e, r, q) => markQ(e, QS(e), keyOf(e, r), r.answers, r.marks, q);
  const okQ = (e, r, q) => { const Q = QS(e)[q] || {}; if (r.marks || Q.teacher) return markOf(e, r, q) >= W(e, q) / 2; return r.answers[q] >= 0 && r.answers[q] === keyOf(e, r)[q]; };
  const partScores = (e, r) => { let q0 = 0; return specOf(e).parts.map(p => { let s = 0, m = 0; for (let q = q0; q < q0 + (+p.count || 0); q++) { m += W(e, q); s += r.absent ? 0 : markOf(e, r, q); } q0 += +p.count || 0; return [Math.round(s * 100) / 100, m]; }); };
  const skey = (sid, name, cls) => sid || ('n:' + A.normKey(name || '') + '|' + (cls || ''));
  const legend = e => { const sp = specOf(e), en = sp.lang === 'en', L = DinaOMR.LABELS[en ? 'en' : 'ar']; let q = 1; return sp.parts.map(p => { const a = q, b = q + (+p.count || 0) - 1; q = b + 1; const n = p.type === 'tf' ? 2 : +p.options || 4, ls = L[p.type || 'mcq'].slice(0, n); if (p.type === 'essay') return `${a}–${b}: ${en ? 'Essay — marked by the teacher in the grey rows' : 'مقالي — يرصد المعلم الدرجة في الصفوف الرمادية'}`; return `${a}–${b}: ${(en ? QT_EN : QT)[p.type || 'mcq']}${p.type === 'tf' ? (en ? ' (T = True, F = False)' : ' (ص = صح، خ = خطأ)') : ` (${ls[0]}–${ls[ls.length - 1]})`}`; }).join(' · '); };
  let st = { view: 'list', exam: null, tab: 'key' };
  // ذاكرة مؤقتة للتنقل الفوري بين التبويبات (تُحدَّث بعد كل حفظ)
  const CACHE = new Map(), cget = (k, fn) => { if (!CACHE.has(k)) CACHE.set(k, fn().catch(e => { CACHE.delete(k); throw e; })); return CACHE.get(k); }, cdel = pre => [...CACHE.keys()].forEach(k => k.startsWith(pre) && CACHE.delete(k));
  const resOf = e => cget('re:' + e.id, () => api.list('paper_results', { exam_id: e.id })).then(l => l.map(x => ({ ...x })));
