    const XM = X ? (X.meta || {}) : null, XP = X ? (XM.periods || Math.max(1, ...(X.slots || []).map(x => x.p + 1))) : 0, XD = X ? (XM.days || [0, 1, 2, 3, 4]) : [];
    const mn = t => { const [h, m] = String(t || '0:0').split(':'); return (+h) * 60 + (+m || 0); };
