    let tg = targets(); let cur = tg.some(t => t[0] === c.cur) ? c.cur : (tg[0] || [])[0];
    const M = !!MASTER[c.kind];
    const vLbl = v => `${v.label}${v.status === 'ds' ? '' : v.status === 'approved' ? ' (المعتمد)' : v.scheduled ? ' (مجدول)' : ' (مسودة)'}`;
