  const dots = y => `<span class="lv-dots" aria-hidden="true">${KEYS.filter(k => (y[k] || '').trim()).map(k => `<i style="--c:${IC[k][0]}"></i>`).join('')}${safe(y.llink) ? `<i style="--c:${IC.llink[0]}"></i>` : ''}${exOf(y).length ? `<i style="--c:#5F7896"></i>` : ''}</span>`;
