      const RC = ['الطالب', 'الفصل', 'الحالة', 'متى', 'الوقت', 'الدقائق', 'ملاحظة'], sub = `${DAYS[dow(day)]} ${A.arDate ? A.arDate(day) : AR(day)}`;
