      sel = -1; render(); const xml = new XMLSerializer().serializeToString(svg).replace('<svg', `<svg width="${W}" height="${H}"`);
      const img = new Image(); img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(xml); await img.decode();
