        nohw: () => ({ title: 'معلمون بلا واجبات هذا الأسبوع', cols: ['المعلم', 'الحصص'], rows: noHw.map(r => ({ cells: [`<b>${esc(r.name || '')}</b>`, AR(r.n)], q: r.name || '' })) }),
