    try { CLS = ids.length ? await api.list('classes', { section_id: ids }) : []; } catch (_) { CLS = []; }
    (S.allClasses || []).concat(S.classes || []).forEach(c => { if (!CLS.some(x => x.id === c.id)) CLS.push(c); });
