  let tm = null;
  const changed = () => { clearTimeout(tm); tm = setTimeout(() => { STU = null; CLS = null; window.dispatchEvent(new CustomEvent('dina-students-changed')); A.syncStudentsNow(); if (A._attRefresh) { try { A._attRefresh(); } catch (_) { } } }, 1500); };
